internal.body:
if (mode <= 0 || mode > MAX_MODE) {
  throw new fr.sorbonne_u.exceptions.PreconditionException("mode > 0 && mode <= MAX_MODE");
}
if (mode == 1) return 300.0;
if (mode == 2) return 400.0;
if (mode == 3) return 500.0;
if (mode == 4) return 1000.0;
return 1500.0;

if (mode <= 0 || mode > MAX_MODE) {
  throw new fr.sorbonne_u.exceptions.PreconditionException("mode > 0 && mode <= MAX_MODE");
}
if (mode == 1) return fr.sorbonne_u.components.hem2025e1.equipments.washingmachine.WashingMachineImplementationI.WashProgram.DELICATE;
if (mode == 2) return fr.sorbonne_u.components.hem2025e1.equipments.washingmachine.WashingMachineImplementationI.WashProgram.ECO;
if (mode == 3) return fr.sorbonne_u.components.hem2025e1.equipments.washingmachine.WashingMachineImplementationI.WashProgram.QUICK;
if (mode == 4) return fr.sorbonne_u.components.hem2025e1.equipments.washingmachine.WashingMachineImplementationI.WashProgram.STANDARD;
return fr.sorbonne_u.components.hem2025e1.equipments.washingmachine.WashingMachineImplementationI.WashProgram.INTENSIVE;

if (mode <= 0 || mode > MAX_MODE) {
  throw new fr.sorbonne_u.exceptions.PreconditionException("mode > 0 && mode <= MAX_MODE");
}
fr.sorbonne_u.components.hem2025e1.equipments.washingmachine.WashingMachineImplementationI.WashProgram program = getProgramByMode(mode);
washer.selectProgram(program);

upMode.body:
try {
  if (currentMode >= MAX_MODE) return false;
  setProgramByMode(currentMode + 1);
  currentMode++;
} catch(Exception e) {
  return false;
}
return true;

downMode.body:
try {
  if (currentMode <= 1) return false;
  setProgramByMode(currentMode - 1);
  currentMode--;
} catch(Exception e) {
  return false;
}
return true;

setMode.body:
try {
  if (modeIndex <= 0 || modeIndex > MAX_MODE) return false;
  setProgramByMode(modeIndex);
  currentMode = modeIndex;
} catch(Exception e) {
  return false;
}
return true;

suspend.body:
try {
  washer.suspendCycle();
  isSuspended = true;
} catch(Exception e) {
  return false;
}
return true;

resume.body:
try {
  // Resume cycle if suspended
  if (isSuspended) {
    washer.resumeCycle();
  }
  isSuspended = false;
} catch(Exception e) {
  return false;
}
return true;
